function updateStatus(){if(!race)return;renderCarMessages();updateRacePoints();updateMovePrompt();updateEngineAudio();const fresh=race.slots.some(p=>p&&!p.isDemo&&!p.countryFlag&&Date.now()+serverOffset-p.joinedAt<30000);const suggestion=$('countrySuggestion');if(suggestion.hidden===fresh){suggestion.hidden=!fresh;scheduleRaceFit()}renderSpotlight();updateArrivalZone();const r=race,roundStage=raceRoundStage(r.round,r.settings.roundsPerRace),banner=$('roundStageBanner'),elapsed=(Date.now()+serverOffset-r.startsAt)/1000;const transition=r.roundTransition,showTransition=transition?.immediate&&Date.now()+serverOffset-transition.at<5000;banner.hidden=!r.settings.running||r.settings.paused||(!showTransition&&(r.winner!==null||elapsed>3));banner.textContent=showTransition?raceRoundStage(transition.from,r.settings.roundsPerRace).title+' COMPLETE · '+raceRoundStage(transition.to,r.settings.roundsPerRace).title:roundStage.title+(elapsed<0?' · GET READY':' · GO!');const remaining=Math.max(0,Math.ceil((r.startsAt-Date.now()-serverOffset)/1000));if(!r.slots.slice(0,r.settings.cars).some(Boolean)){$('raceStatus').textContent='WAITING FOR PLAYERS';$('countdown').hidden=true;banner.hidden=true;return}$('countdown').hidden=remaining===0||!r.settings.running||r.settings.paused||r.winner!==null;$('countdownNumber').textContent=Math.min(3,remaining);$('countryPrompt').hidden=!remaining||!r.slots.some(p=>p&&!p.isDemo&&!p.countryFlag);if(!r.settings.running){$('raceStatus').textContent='STOPPED';$('countdown').hidden=true;return}if(r.settings.paused){$('raceStatus').textContent='PAUSED';return}if(r.winner!==null){const seconds=Math.max(0,Math.ceil((r.nextGameAt-Date.now()-serverOffset)/1000));$('raceStatus').textContent=roundStage.title+' COMPLETE · '+(r.winnerResult?.noWinner?'No winners':(r.winnerResult?.name||r.slots[r.winner]?.name||'WINNER')+' WINS')+(r.settings.autoRestart?' · NEXT '+roundStage.nextTitle+' IN '+seconds+'s':'');return}const left=Math.max(0,Math.ceil(((r.roundEndsAt||r.startsAt+(r.settings.roundSeconds||90)*1000)-Date.now()-serverOffset)/1000));$('raceStatus').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0')+' LEFT'}
function showSupporters(i){const player=race?.slots[i];$('supporterTitle').textContent='CAR '+(i+1);$('supporterList').replaceChildren(node('strong','',player?.name||'OPEN SLOT'),node('p','',player?Math.floor(player.distance/race.settings.step)+' POINTS':'Comment this car number to join'),node('p','','GO moves your car. Likes are optional. Points have no monetary value.'));$('supporters').showModal()}
