let winnerKey='';function renderWinner(){const r=race,box=$('winner'),key=r.round+':'+r.winner;box.hidden=r.winner===null||r.roundTransition?.immediate===true;if(key===winnerKey)return;winnerKey=key;box.replaceChildren();if(r.winner===null||r.roundTransition?.immediate)return;box.append(node('p','round-result-heading',raceRoundStage(r.round,r.settings.roundsPerRace).title+' COMPLETE'));const p=r.winnerResult||r.slots[r.winner];if(!p||p.noWinner){box.append(node('h2','','No player finished ahead'));return}box.append(avatar(p),node('h2','',p.name),node('p','','ROUND LEADER'),node('strong','winner-score',Math.floor(p.assistScore??p.score??0)+' POINTS'),node('small','','FREE PLAY · POINTS ONLY'))}
function renderSettings(){const form=$('settings');if(form.dataset.dirty!=='true'&&!form.contains(document.activeElement)&&document.activeElement?.form!==form)for(const [k,v]of Object.entries(race.settings)){const input=form.elements.namedItem(k);if(input){if(input.type==='checkbox')input.checked=v;else input.value=v}}const root=$('slotSettings'),key=JSON.stringify([race.settings.cars,race.flags]);if(root.dataset.key===key||root.contains(document.activeElement))return;root.dataset.key=key;root.replaceChildren();for(let i=0;i<race.settings.cars;i++){const row=node('form','slot-row'),input=node('input'),button=node('button','','ذخیرهٔ بیرق');input.value=race.flags[i];input.maxLength=8;row.append(node('label','','موتر '+(i+1)),input,button);row.onsubmit=e=>{e.preventDefault();send('race-slot',{index:i,flag:input.value.trim()})};root.append(row)}}
function renderManagement(){const list=$('managePlayers'),key=JSON.stringify([...race.slots,...race.queue].map(p=>[p?.id,p?.name,p?.avatar]));if(list.dataset.key!==key&&!list.contains(document.activeElement)){list.dataset.key=key;list.replaceChildren();[...race.slots.map((p,i)=>p&&!p.isDemo?{...p,label:'موتر '+(i+1)}:null),...race.queue.map(p=>({...p,label:'انتظار'}))].filter(Boolean).forEach(p=>{const row=node('div','manage-row'),name=node('input'),photo=node('input'),save=node('button','','ذخیره نام و عکس'),remove=node('button','','خروج'),block=node('button','danger','مسدود');name.value=p.name;name.maxLength=40;name.setAttribute('aria-label','نام '+p.name);photo.type='file';photo.accept='image/png,image/jpeg,image/webp';photo.setAttribute('aria-label','عکس '+p.name);let image=p.avatar;photo.onchange=async()=>{const f=photo.files[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>5000000){notify('عکس PNG، JPEG یا WebP تا ۵ مگابایت انتخاب کنید.');return}const bitmap=await createImageBitmap(f);const c=document.createElement('canvas');c.width=c.height=100;const size=Math.min(bitmap.width,bitmap.height);c.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,100,100);image=c.toDataURL('image/jpeg',.8);bitmap.close()};save.onclick=()=>send('race-edit',{userId:p.id,name:name.value.trim(),avatar:image});remove.onclick=()=>send('race-remove',{userId:p.id});block.onclick=()=>send('remove-user',{userId:p.id});row.append(node('span','',p.label),name,photo,save,remove,block);list.append(row)})}const restore=$('restorePlayers');restore.replaceChildren();const people=new Map((race.removed||[]).map(p=>[p.id,p.name]));for(const id of lastMessage.snapshot.blockedUsers||[])if(!people.has(id))people.set(id,id);for(const [id,name]of people){const row=node('div','manage-row'),button=node('button','','رفع مسدودی / برگشت به صف');button.onclick=()=>send('race-restore',{userId:id});row.append(node('span','',name),button);restore.append(row)}}
function frameLevel(){return race?.settings.ring||'cloud'}
