$('panelToggle').onclick=()=>{$('panel').hidden=!$('panel').hidden};$('closePanel').onclick=()=>{$('panel').hidden=true};$('unlock').onclick=()=>{token=$('adminKey').value.trim();sessionStorage.setItem('race-admin',token);send('auth',{token});$('adminKey').value=''};$('connect').onclick=()=>send('connect',{username:$('username').value.trim()});$('disconnect').onclick=()=>send('disconnect');$('startDemo').onclick=()=>send('demo-start');$('stopDemo').onclick=()=>send('demo-stop');$('newRound').onclick=()=>send('race-new');$('settings').onsubmit=e=>{e.preventDefault();const settings={};for(const el of e.target.elements)if(el.name)settings[el.name]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'||el.type==='color'||el.type==='hidden'?el.value:Number(el.value);e.target.dataset.dirty='';send('race-settings',{settings})};document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>send('race-demo',{action:b.dataset.test,userId:$('testId').value,name:$('testName').value,count:Number($('testCount').value),content:$('testCountry').value.trim()}));
