function renderModes(){const manual=race.settings.entryMode==='manual';$('playMode').value='likes';$('manualMovement').hidden=true;$('modeManual').setAttribute('aria-pressed',String(manual));$('modeLikes').setAttribute('aria-pressed',String(!manual));const prompt=$('manualJoinPrompt');prompt.hidden=!manual||race.settings.running;prompt.textContent='COMMENT 1–'+race.settings.cars+' TO JOIN · WAIT FOR HOST';$('modeDescription').textContent='ورود با شمارهٔ موتر و انتخاب اختیاری کشور؛ حرکت با کامنت GO یا هر ۱۰ لایک. امتیاز فقط داخل بازی است و جایزهٔ مالی ندارد.'}
