function renderDriverRoster(){const root=$('driverRoster');root.replaceChildren();for(let i=0;i<race.settings.cars;i++){const p=race.slots[i],card=node('button','roster-card');card.type='button';card.onclick=()=>showSupporters(i);card.append(avatar(p),node('span','roster-number',String(i+1)),node('strong','roster-name',p?.name||'OPEN SLOT'),node('span','roster-distance',Math.floor(p?.distance||0)+'m'));root.append(card)}}

function racerFlag(person,index){return person?.isDemo?race.flags[index]:person?.countryFlag||''}

let lastRaceLeader=null,lastLeaderRound=0;
function renderCompetition(){const rows=race.slots.slice(0,race.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p).sort((a,b)=>b.p.distance-a.p.distance||a.i-b.i),top=rows[0];if(lastLeaderRound!==race.round){lastRaceLeader=null;lastLeaderRound=race.round}for(let position=0;position<rows.length;position++){const {p,i}=rows[position],card=$('driverRoster').children[i],lane=$('track').querySelectorAll(':scope > .lane')[i];if(!card||!lane)continue;let badge=card.querySelector('.roster-position');if(!badge){badge=node('span','roster-position');card.append(badge)}badge.textContent='P'+(position+1);const isLead=position===0&&p.distance>0;card.classList.toggle('race-leader',isLead);lane.classList.toggle('race-leader',isLead);card.style.setProperty('--progress',Math.min(100,p.distance/race.settings.length*100)+'%')}if(top?.p.distance>0){if(lastRaceLeader!==null&&lastRaceLeader!==top.p.id&&race.settings.effects&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$('track').classList.remove('overtake');void $('track').offsetWidth;$('track').classList.add('overtake');setTimeout(()=>$('track').classList.remove('overtake'),900)}lastRaceLeader=top.p.id}document.body.classList.toggle('final-sprint',!!top&&top.p.distance/race.settings.length>=.8)}

for(const [id,action]of [['raceStart','start'],['racePause','pause'],['raceResume','resume'],['raceStop','stop']])$(id).onclick=()=>send('race-control',{action});
function renderRaceControls(){const s=race.settings;if(window.updatePanelMotion)window.updatePanelMotion(s);const state=!s.running?'متوقف کامل':s.paused?'توقف موقت':Date.now()+serverOffset<race.startsAt?'شمارش معکوس':'در حال مسابقه';$('raceControlStatus').textContent='وضعیت: '+state;$('racePause').disabled=!s.running||s.paused;$('raceResume').disabled=!s.running||!s.paused;$('raceStop').disabled=!s.running;}

let selectedAuditRound='current';
function currentAudit(){const rows=Object.values(race.roundAudit||{}).map(x=>({...x}));for(const p of race.slots){if(!p||p.isDemo)continue;let x=rows.find(x=>x.id===p.id);if(!x){x={id:p.id,name:p.name,likePoints:0,commentPoints:0};rows.push(x)}x.score=p.distance/race.settings.step;x.reason='RACE IN PROGRESS'}return {round:race.round,rows}}
function chosenAudit(){return selectedAuditRound==='current'?(race.winner!==null?race.roundReports?.find(x=>x.round===race.round):currentAudit()):(race.roundReports||[]).find(x=>String(x.round)===selectedAuditRound)}
function auditTable(report){const table=node('table','audit-table'),head=node('tr');for(const title of ['PLAYER','POINTS','GO POINTS','LIKE POINTS','RESULT'])head.append(node('th','',title));const thead=node('thead');thead.append(head);table.append(thead);const body=node('tbody');for(const row of report?.rows||[]){const tr=node('tr',row.winner?'audit-winner':'');for(const v of [row.name,Math.floor(row.score||0),row.commentPoints||0,row.likePoints||0,row.winner?'ROUND LEADER':row.reason||'IN PROGRESS'])tr.append(node('td','',String(v)));body.append(tr)}table.append(body);return table}
function renderAudit(){const select=$('auditRound');const options=[['current','دور جاری'],...(race.roundReports||[]).map(r=>[String(r.round),'دور '+r.round])];const key=JSON.stringify(options);if(select.dataset.key!==key){select.dataset.key=key;select.replaceChildren();for(const [value,label]of options){const o=node('option','',label);o.value=value;select.append(o)}select.value=selectedAuditRound}const report=chosenAudit();const panel=$('auditPanel');const signature=JSON.stringify(report);if(panel.dataset.key!==signature){panel.dataset.key=signature;panel.replaceChildren(auditTable(report))}const live=$('liveAudit');live.hidden=!(race.settings.showResultTable&&race.winner!==null);const final=(race.roundReports||[]).find(r=>r.round===race.round);const liveKey=JSON.stringify(final);if(live.dataset.key!==liveKey){live.dataset.key=liveKey;live.replaceChildren(node('h2','','ROUND '+race.round+' · RACE POINTS'),auditTable(final,true))}}
$('auditRound').onchange=e=>{selectedAuditRound=e.target.value;renderAudit()};$('showAudit').onclick=()=>send('race-settings',{settings:{showResultTable:!race.settings.showResultTable}});$('downloadAudit').onclick=()=>{const report=chosenAudit();if(!report)return;const q=String.fromCharCode(34),cell=v=>q+String(v??'').replace(/^[=+@\-\t\r]/,m=>String.fromCharCode(39)+m).replaceAll(q,q+q)+q;const rows=[['ROUND','PLAYER','POINTS','GO POINTS','LIKE POINTS','RESULT'],...report.rows.map(x=>[report.round,x.name,x.score,x.commentPoints,x.likePoints,x.reason])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=node('a');a.href=url;a.download='race-round-'+report.round+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

let raceFitPending=false;function scheduleRaceFit(){if(!screen||raceFitPending)return;raceFitPending=true;requestAnimationFrame(()=>{raceFitPending=false;const road=document.querySelector('.road');if(!road)return;const lane=document.querySelector('.lane');const carScale=Math.min(innerWidth<700?1:1.45,(lane?.clientWidth||80)*.70/64);$('stage').style.setProperty('--race-car-scale',String(carScale));const headers=[...document.querySelectorAll('.lane>.driver')];headers.forEach(e=>e.style.height='auto');const maxHeader=Math.max(0,...headers.map(e=>e.getBoundingClientRect().height));headers.forEach(e=>e.style.height=maxHeader+'px');const fullView=window.visualViewport?.height||innerHeight;const safe=race?.settings.liveBottomInsetPercent??28;const view=fullView*(1-safe/100);document.documentElement.style.setProperty('--live-safe-bottom',safe+'svh');const stage=$('stage'),minimumRoad=Math.min(fullView<650?(race?.queue.length?60:80):120,view*.2);stage.style.setProperty('--minimum-road',minimumRoad+'px');const overhead=stage.getBoundingClientRect().height-road.getBoundingClientRect().height;const height=Math.max(minimumRoad,Math.min(view*.65,view-overhead-8));const value=Math.round(height)+'px';if(stage.style.getPropertyValue('--race-road-height')!==value)stage.style.setProperty('--race-road-height',value);const center=document.querySelector('.race-center'),rect=road.getBoundingClientRect();const rail=$('supportSpotlight');if(rail)center.style.setProperty('--support-space',Math.max(70,rect.bottom-rail.getBoundingClientRect().top-6)+'px');center.style.setProperty('--move-dock-top',Math.round(rect.top-center.getBoundingClientRect().top+5)+'px');center.style.setProperty('--move-prompt-top',Math.round(rect.top-center.getBoundingClientRect().top+rect.height/2)+'px')})}window.addEventListener('resize',scheduleRaceFit);window.visualViewport?.addEventListener('resize',scheduleRaceFit);document.fonts.ready.then(scheduleRaceFit);

function renderCarAppearance(){const root=$('carAppearance'),key=JSON.stringify([race.settings.cars,race.carStyles]);if(root.dataset.key===key||root.contains(document.activeElement))return;root.dataset.key=key;root.replaceChildren();for(let i=0;i<race.settings.cars;i++){const style=race.carStyles?.[i]||{color:palette[i],model:'gt'};const form=node('form','car-style-row'),label=node('strong','','موتر '+(i+1)),color=node('input'),model=node('select'),save=node('button','','ذخیرهٔ مدل و رنگ');color.type='color';color.value=style.color;color.setAttribute('aria-label','رنگ موتر '+(i+1));model.setAttribute('aria-label','مدل موتر '+(i+1));for(const [value,title]of [['formula','Formula · فرمول'],['gt','GT · سوپراسپورت'],['rally','Rally · رالی']]){const o=node('option','',title);o.value=value;model.append(o)}model.value=style.model;form.append(label,color,model,save);form.onsubmit=e=>{e.preventDefault();send('race-style',{index:i,color:color.value,model:model.value})};root.append(form)}}

$('modeManual').onclick=()=>send('race-settings',{settings:{entryMode:'manual',autoRestart:false}});

function renderSpotlight(){if(!race)return;const root=$('supportSpotlight'),people=race.slots.map((p,i)=>p&&!p.isDemo?{...p,lane:i+1}:null).filter(Boolean).sort((a,b)=>b.distance-a.distance).slice(0,race.settings.likerCount),key=JSON.stringify([people,race.settings.cars]);root.hidden=false;if(root.dataset.key===key)return;root.dataset.key=key;root.replaceChildren(node('div','country-edge-prompt','Country · optional'));const group=node('section','support-group');group.dataset.kind='players';group.append(node('h3','','PLAYERS'));const list=node('div','support-list');for(const p of people){const card=node('div','spotlight-card');card.append(avatar(p),node('strong','',p.name),node('b','',Math.floor(p.distance/race.settings.step)+' PTS'));list.append(card)}if(!people.length)list.append(node('small','support-empty','Comment 1–'+race.settings.cars+' to join'));group.append(list);root.append(group);updateArrivalZone()}

$('manualInputMethod').onchange=e=>send('race-settings',{settings:{playMode:e.target.value}});





function renderCarMessages(){if(!race)return;const now=Date.now()+serverOffset;document.querySelectorAll('.lane').forEach((lane,i)=>{let label=lane.querySelector('.car-full-message');const m=race.carMessages?.[i],visible=m&&m.until>now;if(!label){label=node('span','car-full-message','FULL');label.setAttribute('role','status');lane.querySelector('.road').append(label)}label.hidden=!visible})}

$('refreshStudio').onclick=()=>{send('race-refresh-screen');$('refreshStudio').disabled=true;setTimeout(()=>{$('refreshStudio').disabled=false},2000)};

function showAudioStatus(m){const en=localStorage.getItem('race-panel-language')==='en';const labels=en?{ready:'Ready',playing:'Playing',blocked:'Autoplay blocked: click Enable sound in Studio',error:'Playback error',muted:'Muted',loading:'Loading engine'}:{ready:'آماده',playing:'در حال پخش',blocked:'پخش مسدود است؛ در منبع استودیو Enable sound را بزنید',error:'خطای پخش',muted:'صدا خاموش است',loading:'در حال بارگذاری صدا'};$('audioSourceStatus').textContent=(en?'Studio audio: ':'صدای استودیو: ')+(labels[m.status]||m.status)+' · '+(en?'Original engine':'صدای موتور اصلی')+(m.detail?' · '+m.detail:'')}window.addEventListener('race-audio-state',e=>{const m=e.detail;if(screen){$('audioUnlock').hidden=m.status!=='blocked';if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'race-audio-report',...m}))}else showAudioStatus(m)});$('audioUnlock').onclick=()=>{unlockEngineAudio();$('audioUnlock').hidden=true;updateEngineAudio()};

function updateRacePoints(){if(!race)return;const points=race.slots.slice(0,race.settings.cars).map(p=>Math.floor((p?.distance||0)/race.settings.step));document.querySelectorAll('.lane').forEach((lane,i)=>{const driver=lane.querySelector('.driver');let box=driver.querySelector('.driver-points');if(!box){box=node('div','driver-points');box.append(node('strong','point-total'),node('small','point-rival'),node('small','point-help'));const gift=driver.querySelector('.car-gift');driver.insertBefore(box,gift)}const total=points[i],rival=Math.max(0,...points.filter((_,n)=>n!==i)),p=race.slots[i];const value=box.querySelector('.point-total');if(value.dataset.points!==String(total)){value.dataset.points=total;value.textContent=total+' PTS';value.classList.remove('point-gain');void value.offsetWidth;value.classList.add('point-gain')}box.querySelector('.point-rival').textContent='VS '+rival;const events=(p?.assistHistory||[]).filter(x=>Date.now()+serverOffset-x.at<10000);const speed=events.length?events.reduce((sum,x)=>sum+x.points,0)/Math.max(1,Math.min(10,(Date.now()+serverOffset-events[0].at)/1000+1)):0;box.querySelector('.point-help').textContent=p&&!p.isDemo?'HELP '+(p.assistPoints||0)+' · '+speed.toFixed(1)+'/s':('AI '+(p?.aiLevel||race.settings.difficulty).toUpperCase());box.setAttribute('aria-label',total+' race points, strongest rival '+rival+' points')})}
window.testRaceEngine=()=>{unlockEngineAudio();if(authorized){send('race-settings',{settings:{sound:true,engineSound:true,engineVolume:25}});send('race-audio-test',{kind:'engine'})}else RaceSound.test('engine')};function unlockEngineAudio(){try{audio=RaceSound.unlock(audio)}catch{}}function updateEngineAudio(){RaceSound.update(race,screen,audio)}

for(const event of ['input','change'])document.getElementById('panel').addEventListener(event,e=>{if(e.target.form===$('settings'))$('settings').dataset.dirty='true'});

function drawCloudProfileRing(ctx,cx,cy,_radius,level,time,options={}){const colors={cloud:'#bee7ff',simple:'#b5ddf5',glow:'#71f5d5',silver:'#e6efff',gold:'#ffdf89',ice:'#88edff',fire:'#ffb6a2'},color=colors[level]||colors.cloud;const t=time/1000*(options.speed||1),cloudCount={cloud:16,simple:14,glow:18,silver:20,gold:22,ice:24,fire:26}[level]||16;ctx.save();ctx.strokeStyle=color;ctx.globalAlpha=.38;ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,57,0,Math.PI*2);ctx.stroke();for(let i=0;i<cloudCount;i++){const a=i*Math.PI*2/cloudCount+t*.3,r=57+Math.sin(i*2.4+t)*3,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r,size=5+(Math.sin(i*1.9+t)*.5+.5)*7;const mist=ctx.createRadialGradient(x,y,0,x,y,size);mist.addColorStop(0,color+'a0');mist.addColorStop(1,color+'00');ctx.globalAlpha=.58;ctx.fillStyle=mist;ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill()}for(let i=0;i<12;i++){const a=i*2.399+t*(.25+i*.018),r=62+Math.sin(i*2+t)*7;ctx.globalAlpha=.35+(Math.sin(t*1.4+i)+1)*.25;ctx.fillStyle=color;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,1.2+(i%3)*.5,0,Math.PI*2);ctx.fill()}ctx.restore()}

function updateMovePrompt(){if(!race)return;const prompt=$('movePrompt');prompt.hidden=race.winner!==null;prompt.classList.add('prompt-docked');prompt.classList.remove('prompt-intro')}

setInterval(()=>{if(socket?.readyState===WebSocket.OPEN){if(Date.now()-lastSocketMessageAt>25000){socket.close();return}socket.send(JSON.stringify({type:'race-heartbeat'}))}},8000);
window.addEventListener('online',()=>{if(!socket||socket.readyState>1)connect()});

function updateArrivalZone(){if(!screen)return;const root=$('joinToasts'),prompt=document.querySelector('#supportSpotlight .country-edge-prompt'),stage=$('stage');if(!root||!prompt)return;const body=document.body.getBoundingClientRect(),edge=prompt.getBoundingClientRect(),bottom=edge.top-6,top=Math.max(stage.getBoundingClientRect().top+34,bottom-Math.min(180,innerHeight*.18));root.style.top=Math.max(0,top)+'px';root.style.bottom='auto';root.style.right=Math.max(0,innerWidth-body.right+1)+'px';root.style.height=Math.max(0,bottom-top)+'px';const item=root.lastElementChild;if(item){const capacity=Math.max(1,Math.min(4,Math.floor((root.clientHeight+4)/(item.offsetHeight+4))));while(root.children.length>capacity)root.firstElementChild.remove()}}
window.addEventListener('resize',updateArrivalZone);
setInterval(()=>{updateArrivalZone();if(screen&&socket?.readyState===1)socket.send(JSON.stringify({type:'race-source-health',audio:RaceSound.context?.state||'idle'}))},20000);

if(screen&&'ResizeObserver' in window){const arrivalLayoutObserver=new ResizeObserver(()=>requestAnimationFrame(updateArrivalZone));arrivalLayoutObserver.observe($('supportSpotlight'));arrivalLayoutObserver.observe(document.querySelector('.race-center'))}
